css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 9px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .rec-texto{font-size: 14px; line-height: 1.45;}
.mz .rec-texto b{font-size: 16px;}
.mz .rec-op{font-size: 18px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .rec-op .x{font-size: 20px;}
.mz .tabla-wrap{display: flex; justify-content: center;}
.mz .tabla-mult{display: grid; grid-template-columns: repeat(2, auto); gap: 8px 40px; border: 1.8px solid var(--bosque); border-radius: 11px; padding: 11px 26px;}
.mz .tabla-mult .titulo{grid-column: 1 / -1; text-align: center; font-size: 14px; font-weight: 700; font-family: sans-serif; border-bottom: 1.5px solid var(--bosque); padding-bottom: 4px; margin-bottom: 3px;}
.mz .reng{display: flex; align-items: center; gap: 7px; font-size: 18px; font-weight: 700; font-family: sans-serif;}
.mz .reng .op{min-width: 64px; text-align: right;}
.mz .caja{width: 46px; height: 30px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .calc-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px 34px;}
.mz .resp-fila{display: flex; align-items: center; gap: 7px; font-size: 18px; font-weight: 700; font-family: sans-serif; flex-wrap: wrap;}
.mz .resp-fila .lead{min-width: 78px;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -4px 0 7px;}
.mz .serie{display: flex; gap: 7px; flex-wrap: wrap; align-items: center; margin-bottom: 9px;}
.mz .serie .et{font-size: 12.5px; font-family: sans-serif; font-weight: 700; min-width: 86px;}
.mz .cas{width: 48px; height: 33px; border: 1.6px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-weight: 700; font-size: 17px;}
.mz .cas.dada{background: #ededed;}
.mz .serie .fl{font-size: 14px;}
